public class TagTokenProvider : ITokenDataProvider
{
    private readonly ITagService _tagService;

    public TagTokenProvider(ITagService tagService)
    {
        _tagService = tagService;
    }

    public async Task<IReadOnlyList<IToken>> GetItemsAsync(
        string searchText, CancellationToken ct = default)
    {
        var tags = await _tagService.SearchAsync(searchText, ct);
        return tags.Select(t => new Token { Id = t.Id, Name = t.Name }).ToList();
    }

    public async Task<IToken?> CreateTokenAsync(
        string text, CancellationToken ct = default)
    {
        var tag = await _tagService.CreateAsync(text, ct);
        return new Token { Id = tag.Id, Name = tag.Name };
    }
}
